(function(){'use strict';
const $=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2});let cb,cfg,context;
const panel=document.createElement('section');panel.id='hearts-panel';panel.className='hearts-panel';panel.hidden=true;panel.innerHTML='<h3>Сердца при переработке</h3><label>Как выбирать рецепт<select id="heart-mode"><option value="standard">Обычная переработка</option><option value="auto">Выбирать дешевле по ценам</option><option value="heart">Использовать сердца, где доступны</option></select></label><p class="hint">Сравнивается закупка на текущий объём с возвратом и запасом. Тариф станка одинаковый. Автоподбор использует только варианты с полными ценами.</p><details class="fold"><summary>Сравнение расходов и цены сердец</summary><div class="fold-body" id="heart-comparison"></div></details><p class="heart-rule">Для .4 варианта с сердцами в игровых рецептах нет. Для других ресурсов доступность проверяется по точному рецепту.</p>';
$('chain-options').after(panel);
$('heart-mode').onchange=()=>{cfg.heartMode=$('heart-mode').value;cb(true)};
$('heart-comparison').addEventListener('input',e=>{const id=e.target.dataset.heartPrice;if(!id)return;context.setPrice(id,e.target.value);cb(false)});
window.HeartsUI={render(recipe,config,result,ctx){cfg=config;context=ctx;cb=ctx.save;const plans=result.refiningPlans||[];panel.hidden=!plans.length;if(panel.hidden)return;const focused=document.activeElement?.dataset.heartPrice;$('heart-mode').value=cfg.heartMode||'standard';$('heart-comparison').innerHTML=plans.map(p=>{const heart=window.ALBION_DATA.refineHearts[p.id]?.mats.find(m=>m.id.startsWith('T1_FACTION_')),q=heart?ctx.quote(heart.id):null;return '<div class="heart-comparison-row"><b>'+window.ALBION_DATA.names[p.id]+' · '+(p.id.match(/^T\d+/)?.[0]||'')+'.'+(p.id.match(/@(\d+)$/)?.[1]||'0')+'</b><span>'+(p.heart?'Обычный: '+(p.standard.missing?'нужны цены':fmt(p.standard.cost))+' · с сердцем: '+(p.heart.missing?'нужны цены':fmt(p.heart.cost)):'Сердце недоступно')+'</span><small>В расчёте: '+(p.method==='heart'?'с сердцем':'обычный')+(p.heart&&!p.standard.missing&&!p.heart.missing?' · разница '+fmt(p.standard.cost-p.heart.cost)+' серебра':'')+'</small>'+(heart?'<label>'+window.ALBION_DATA.names[heart.id]+' / шт. · '+q.city+'<input type="number" min="0" data-heart-price="'+heart.id+'" value="'+(q.price||'')+'" placeholder="Введите цену сердца"></label><span class="trans-rule">'+(q.manual?'Ручная цена. Очистите поле для возврата к рынку.':q.price?'Проверенная рыночная цена':q.reason||'Нет цены')+'</span>':'')+'</div>'}).join('');if(focused)$('heart-comparison').querySelector('[data-heart-price="'+focused+'"]')?.focus({preventScroll:true})},marketIds(result){return [...new Set((result.refiningPlans||[]).flatMap(p=>p.marketIds))]}};
})();
